-- The Typist achievement is gone: its only trigger is a query, which the achievement plugin never counts, so no row
-- Could still earn it. A row left from before that is deleted, with its user achievements by cascade, so the cast
-- Back to the recreated enum has no value to reject
DELETE FROM "achievements" WHERE "name" = 'Typist';--> statement-breakpoint
ALTER TABLE "achievements" ALTER COLUMN "name" SET DATA TYPE text;--> statement-breakpoint
DROP TYPE "achievementName";--> statement-breakpoint
CREATE TYPE "achievementName" AS ENUM('ClickerAddict', 'ClickerArchitect', 'ClickerBillionaire', 'ClickerChampion', 'ClickerCompletionist', 'ClickerMillionaire', 'ClickerNovice', 'ClickerPro', 'ClickerSaver', 'ClickerTrillionaire', 'DungeonCrawler', 'DungeonHomeowner', 'DungeonMaster', 'MonsterCatcher', 'MonsterCollector', 'MonsterElite', 'MonsterTrainer', 'EmailMarketer', 'ComplexFlow', 'Flowcharter', 'SystemArchitect', 'Critic', 'CriticalThinker', 'Disliker', 'Hater', 'Liker', 'SuperFan', 'Unliker', 'CenturyClub', 'Chatterbox', 'ConversationKeeper', 'EarlyBird', 'EmojiMaster', 'EssayWriter', 'FileSharer', 'FirstMessage', 'Gossip', 'LinkSharer', 'MessageEditor', 'MessageForwarder', 'MessageMaster', 'NightOwl', 'PinCollector', 'SecondThoughts', 'ShortAndSweet', 'Unpinner', 'Verbose', 'BriefComment', 'Commentator', 'CommentDeleter', 'CommentEditor', 'DetailedPost', 'Novelist', 'PostDeleter', 'PostEditor', 'PosterChild', 'ProlificPoster', 'Inviter', 'PartyHost', 'RoomCreator', 'RoomDestroyer', 'RoomHopper', 'RoomJoiner', 'RoomLeaver', 'RoomRenovator', 'Socialite', 'AllCaps', 'AllLower', 'EmojiLover', 'Meta', 'NumberEnthusiast', 'Palindrome', 'DataCollector', 'Modeler', 'Publisher', 'Respondent', 'ResponseEditor', 'SurveyDeleter', 'SurveyEditor', 'SurveyGuru', 'Surveyor', 'SurveySays', 'DataAnalyst', 'MathWhiz', 'WebDeveloper');--> statement-breakpoint
ALTER TABLE "achievements" ALTER COLUMN "name" SET DATA TYPE "achievementName" USING "name"::"achievementName";